'use strict';
(()=>{
const nav=[...document.querySelectorAll('aside nav button')].find(b=>b.textContent.trim()==='Настройки');
nav.disabled=false;
const page=document.createElement('main');page.id='servercore-page';page.hidden=true;
page.innerHTML=`<div class="breadcrumb">Коммуникации / Настройки</div>
<div class="heading"><div><h1>Servercore и учёт событий</h1><p>Подключение транспорта и проверка ссылок письма</p></div></div>
<div class="demo"><b>Режим проверки — отправка отключена</b><span>Проверочные ссылки работают. Письма не отправляются, тестовые отписки не меняют реальную базу.</span></div>
<section class="panel"><h2>Подключение Servercore</h2><div id="sc-config" class="table-scroll"></div>
<div class="actions"><button class="outline" id="sc-refresh">Обновить настройки</button><button class="outline" id="sc-inspect">Проверить API и домен</button></div>
<p id="sc-connection-status" role="status"></p><p>Стандартная скорость: 20 писем за 5 минут. Повышение — через поддержку Servercore.</p>
<details><summary>Какие параметры нужны для подключения</summary><p>SMTP: smtp.servercore-smtp.com, порт 1126 STARTTLS или 1127 TLS, логин, пароль и адрес отправителя.</p><p>API: ID ресурса и проектный IAM-токен (24 часа) либо реквизиты сервисного пользователя для автоматического обновления токена. Пароли и токены задаются в окружении сервера; здесь показывается только их наличие.</p><p>Для публичных ссылок задайте SALES_PUBLIC_BASE_URL с HTTPS-адресом приложения. Локальные HTTP-ссылки работают только на этом компьютере.</p></details></section>
<section class="panel"><h2>Проверка письма без отправки</h2><p>Выберите сохранённый шаблон. Будут подставлены персональные ссылки переходов, отписки и пиксель открытия. Подготовка и предпросмотр не создают события открытия.</p>
<form id="sc-preview-form"><div class="sc-form-grid"><label>Шаблон<select id="sc-template" required><option value="">Выберите шаблон</option></select></label>
<label>Email для проверки<input id="sc-recipient" type="email" value="preview@example.invalid" maxlength="254" required></label>
<label>Имя<input id="sc-name" value="Тестовый клиент" maxlength="250"></label><label>Компания<input id="sc-company" value="OVER" maxlength="250"></label><label>Город<input id="sc-city" value="Алматы" maxlength="250"></label></div>
<button class="outline" id="sc-prepare">Подготовить проверочное письмо</button></form><p id="sc-preview-status" role="status"></p>
<div id="sc-preview-result" hidden><h3 id="sc-subject"></h3><div class="actions" id="sc-link-actions"></div>
<p>Открытие фиксирует первую загрузку пикселя; оно не доказывает прочтение. Переходы также могут выполнять почтовые проверки. Повторные обращения к одной ссылке не увеличивают счётчик.</p>
<iframe id="sc-frame" title="Проверочное письмо без загрузки внешних ресурсов" sandbox="" referrerpolicy="no-referrer"></iframe>
<details><summary>Подготовленный HTML и заголовки</summary><p>Ссылки предназначены для проверки, не для реальной рассылки.</p><textarea id="sc-html" readonly aria-label="Подготовленный HTML"></textarea><pre id="sc-headers"></pre></details></div></section>
<section class="panel"><div class="section-title"><h2>Собственный учёт событий</h2><button class="outline" id="sc-events-refresh">Обновить события</button></div>
<form id="sc-events-filter" class="sc-form-grid"><label>Источник<select id="sc-mode"><option value="test">Проверочные письма</option><option value="real">Рабочие письма</option></select></label>
<label>Письмо<select id="sc-message"><option value="">Все письма</option></select></label><label>Email<input id="sc-query" maxlength="254" placeholder="Поиск получателя"></label>
<label>Событие<select id="sc-kind"><option value="">Все события</option><option value="open">Открытие</option><option value="click">Переход</option><option value="unsubscribe">Отписка</option></select></label>
<label>Сортировка<select id="sc-direction"><option value="desc">Сначала новые</option><option value="asc">Сначала старые</option></select></label><button class="outline">Применить</button></form>
<p id="sc-event-status" role="status"></p><section class="stats" id="sc-cards"></section><div id="sc-events" class="table-scroll"></div>
<div class="actions"><button class="outline" id="sc-prev">Назад</button><span id="sc-pagination"></span><button class="outline" id="sc-next">Далее</button></div>
<p>События хранятся отдельно от прежней демонстрационной статистики. Доставка и отправка по открытиям и переходам не устанавливаются.</p></section>`;
document.body.append(page);
const $=id=>document.getElementById('sc-'+id), labels={open:'Открытия',click:'Переходы',unsubscribe:'Отписки'};
let pageNumber=1,requestNumber=0,preview=null;
function text(tag,value){const e=document.createElement(tag);e.textContent=value;return e;}
function table(container,head,rows){const t=document.createElement('table'),thead=document.createElement('thead'),tr=document.createElement('tr');for(const h of head)tr.append(text('th',h));thead.append(tr);t.append(thead);const body=document.createElement('tbody');for(const row of rows){const line=document.createElement('tr');for(const cell of row)line.append(text('td',cell));body.append(line);}if(!rows.length){const line=document.createElement('tr'),cell=text('td','Пока нет записей');cell.colSpan=head.length;line.append(cell);body.append(line);}t.append(body);container.replaceChildren(t);}
async function config(){try{const c=await api('/api/servercore');table($('config'),['Параметр','Состояние'],[
['Отправка','Отключена на этапе проверки'],['SMTP',c.smtp_configured?'Параметры заполнены; соединение не проверено':'Нужно заполнить: '+c.smtp_missing.join(', ')],
['API',c.api_configured?'Параметры заполнены; доступ не проверен':'Нужно заполнить: '+c.api_missing.join(', ')],['Обновление IAM-токена',c.token_mode==='service_user'?'Автоматически через сервисного пользователя':c.token_mode==='temporary'?'Временный токен, срок 24 часа':'Не настроено'],['Домен',c.domain||'Не задан']]);$('inspect').disabled=!c.api_configured;}catch(e){$('connection-status').textContent=e.message;}}
async function templates(){const t=await api('/api/templates');$('template').replaceChildren(new Option('Выберите шаблон',''));for(const row of t.templates)$('template').add(new Option(row.name,String(row.id)));}
async function report(){const seq=++requestNumber;try{const params=new URLSearchParams({mode:$('mode').value,kind:$('kind').value,query:$('query').value,direction:$('direction').value,page:String(pageNumber)});if($('message').value)params.set('message_id',$('message').value);const r=await api('/api/mail-tracking?'+params);if(seq!==requestNumber)return;
$('cards').replaceChildren();for(const [kind,title]of Object.entries(labels)){const card=document.createElement('article');card.append(text('span',title),text('strong',String(r.unique[kind])),text('small',`Получателей · зафиксировано: ${r.totals[kind]}`));$('cards').append(card);}
table($('events'),['Время','Получатель','Тема','Событие','Ссылка'],r.history.map(e=>[new Date(e.occurred_at).toLocaleString('ru-RU',{timeZone:'Asia/Qyzylorda'}),e.recipient,e.subject,labels[e.kind],e.target]));
$('pagination').textContent=`${r.pagination.page} / ${r.pagination.pages} · событий: ${r.pagination.total}`;$('prev').disabled=!r.pagination.has_previous;$('next').disabled=!r.pagination.has_next;
$('event-status').textContent=(r.mode==='test'?'Проверочные письма':'Рабочие письма')+`: ${r.messages_count}. Отправка отключена.`;
if(!$('message').value){$('message').replaceChildren(new Option('Все письма',''));for(const m of r.messages)$('message').add(new Option(`${m.recipient} — ${m.subject}`,m.id));}
}catch(e){if(seq===requestNumber)$('event-status').textContent=e.message;}}
$('refresh').onclick=config;$('inspect').onclick=async()=>{const b=$('inspect');b.disabled=true;try{const r=await api('/api/servercore',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'inspect'})});$('connection-status').textContent=`API доступен. Ресурс: ${r.resource.name} (${r.resource.status}). Письма не отправлялись.`;if(r.verification)$('connection-status').textContent+=' '+Object.entries(r.verification).map(([key,value])=>key+': '+(value?'OK':'не подтверждено')).join('; ');}catch(e){$('connection-status').textContent=e.message;}finally{b.disabled=false;}};
function previewDisplay(html){const d=new DOMParser().parseFromString(html,'text/html');for(const tag of d.querySelectorAll('script,iframe,object,embed,form,meta,base,link'))tag.remove();for(const a of d.querySelectorAll('a'))a.removeAttribute('href');return `<meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src data:; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'">`+d.documentElement.outerHTML;}
$('preview-form').onsubmit=async event=>{event.preventDefault();$('prepare').disabled=true;try{preview=await api('/api/mail-tracking/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({template_id:Number($('template').value),recipient:$('recipient').value,values:{name:$('name').value,company:$('company').value,city:$('city').value},is_test:true,send:false})});$('preview-result').hidden=false;$('subject').textContent=preview.subject;$('html').value=preview.html;$('headers').textContent=JSON.stringify(preview.headers,null,2);$('frame').srcdoc=previewDisplay(preview.html);$('link-actions').replaceChildren();
const action=(label,url,isClick)=>{const b=text('button',label);b.type='button';b.className='outline';b.onclick=async()=>{b.disabled=true;try{const response=await fetch(url,{redirect:isClick?'manual':'follow',cache:'no-store',referrerPolicy:'no-referrer'});if(!isClick&&!response.ok)throw Error('Ссылка недоступна.');await report();$('preview-status').textContent='Проверочное событие зафиксировано. Повторное обращение не увеличивает счётчик.';}catch(e){$('preview-status').textContent=e.message;}finally{b.disabled=false;}};$('link-actions').append(b);};
action('Проверить открытие',preview.pixel_url,false);preview.clicks.forEach((c,i)=>action('Проверить переход '+(i+1),c.url,true));const unsub=text('a','Открыть проверочную отписку');unsub.href=preview.unsubscribe_url;unsub.target='_blank';unsub.rel='noopener noreferrer';unsub.className='outline';$('link-actions').append(unsub);
$('mode').value='test';$('query').value='';$('kind').value='';$('message').value='';pageNumber=1;await report();$('preview-status').textContent=preview.note;
}catch(e){$('preview-status').textContent=e.message;}finally{$('prepare').disabled=false;}};
$('events-filter').onsubmit=e=>{e.preventDefault();pageNumber=1;report();};$('mode').onchange=()=>{$('message').replaceChildren(new Option('Все письма',''));pageNumber=1;report();};$('events-refresh').onclick=report;$('prev').onclick=()=>{pageNumber=Math.max(1,pageNumber-1);report();};$('next').onclick=()=>{pageNumber++;report();};
document.querySelector('aside nav').addEventListener('click',event=>{const target=event.target.closest('button');if(!target||target.disabled)return;if(target===nav){document.querySelectorAll('body>main').forEach(p=>p.hidden=true);page.hidden=false;document.querySelectorAll('aside nav button').forEach(b=>{b.classList.remove('active');b.removeAttribute('aria-current');});nav.classList.add('active');nav.setAttribute('aria-current','page');document.title='Servercore и учёт событий';try{sessionStorage.setItem('servercore-open','1');}catch{}Promise.all([config(),templates(),report()]).catch(e=>$('connection-status').textContent=e.message);}else{page.hidden=true;try{sessionStorage.removeItem('servercore-open');}catch{}}});
const analytics=document.getElementById('campaign-statistics');if(analytics){const button=text('button','Собственный учёт открытий и переходов');button.className='outline';button.onclick=()=>nav.click();analytics.querySelector('.heading').append(button);}
try{if(sessionStorage.getItem('servercore-open')==='1')nav.click();}catch{}
})();
